import { createClient, SupabaseClient } from '@supabase/supabase-js';
import jwt from 'jsonwebtoken';

const supabaseUrl = process.env.SUPABASE_URL;
const supabaseServiceRoleKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

let supabaseAdmin: SupabaseClient | null = null;

function getSupabaseAdmin(): SupabaseClient {
  if (!supabaseAdmin) {
    if (!supabaseUrl || !supabaseServiceRoleKey) {
      throw new Error('SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY environment variables are required for auth');
    }
    supabaseAdmin = createClient(supabaseUrl, supabaseServiceRoleKey);
  }
  return supabaseAdmin;
}

export interface User {
  id: string;
  email: string;
  name: string;
  avatarUrl?: string;
}

export interface TokenData {
  sub: string;
  email?: string;
  name?: string;
}

export async function verifySupabaseToken(authToken: string): Promise<User | null> {
  try {
    const supabase = getSupabaseAdmin();
    const { data, error } = await supabase.auth.getUser(authToken);

    if (error || !data.user) {
      return null;
    }

    const user = data.user;
    return {
      id: user.id,
      email: user.email || '',
      name: user.user_metadata?.full_name || user.user_metadata?.name || user.email?.split('@')[0] || 'Anonymous',
      avatarUrl: user.user_metadata?.avatar_url || user.user_metadata?.picture
    };
  } catch {
    return null;
  }
}

export function createAccessToken(userId: string, email?: string, name?: string): string {
  const jwtSecret = process.env.JWT_SECRET;
  const jwtExpiration = process.env.JWT_EXPIRATION || '30d';

  if (!jwtSecret) {
    throw new Error('JWT_SECRET environment variable is required');
  }

  const tokenData: TokenData = { 
    sub: userId,
    email,
    name
  };

  return jwt.sign(tokenData, jwtSecret, { expiresIn: jwtExpiration as any });
}

export function verifyAccessToken(token: string): TokenData | null {
  const jwtSecret = process.env.JWT_SECRET;

  if (!jwtSecret) {
    throw new Error('JWT_SECRET environment variable is required');
  }

  try {
    const decoded = jwt.verify(token, jwtSecret) as TokenData;
    return decoded;
  } catch {
    return null;
  }
}

export function isAuthConfigured(): boolean {
  return !!(
    process.env.SUPABASE_URL && 
    process.env.SUPABASE_SERVICE_ROLE_KEY && 
    process.env.JWT_SECRET
  );
}

import { Stream } from '@motiadev/stream-client-browser';

const API_BASE_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000';
const WS_URL = import.meta.env.VITE_WS_URL || 'ws://localhost:3000';

function getAuthToken(): string | null {
  return localStorage.getItem('tt_access_token');
}

function getAuthHeaders(): Record<string, string> {
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  };

  const token = getAuthToken();
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  return headers;
}

let streamInstance: Stream | null = null;
let isConnecting = false;

function getStream(): Stream {
  if (streamInstance) {
    return streamInstance;
  }

  if (isConnecting) {
    throw new Error('Stream connection already in progress');
  }

  // Only create stream connection if user is authenticated
  const token = getAuthToken();
  if (!token) {
    throw new Error('Authentication required for stream connection');
  }

  try {
    isConnecting = true;
    streamInstance = new Stream(WS_URL, {
      headers: {
        Authorization: `Bearer ${token}`
      }
    });
    return streamInstance;
  } catch (error) {
    streamInstance = null;
    throw error;
  } finally {
    isConnecting = false;
  }
}

export function resetStream(): void {
  if (streamInstance) {
    try {
      streamInstance.close();
    } catch {
    }
    streamInstance = null;
  }
}

